#!/usr/bin/env python3
"""Replace the installed tawk.to widget with the owner-approved Chatwoot widget. No ERP/DNS/Caddy changes."""
import argparse
import base64
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import shutil
import stat
import tempfile

MANIFEST = json.loads('''{"assets/support-contact-config.js":{"previous":["9e42a02662d3fa181aa44a51442cce68fddfa896fb15982b5dadd51cd4596e05"],"sha256":"2a8894dd41e0c6b07c561ffc32f7cdfec7eaf6b8b8b865c8913d5be2b8e3149c","data":""},"assets/support-chat.js":{"previous":["1462dc7fa443bd39b1e17bee53b95526e79f21dbc1650db0da1d1081275a376d","30099ab54ea6c31c3505c652429d37e3b2d0cc7c116a3bbafe484c82101ba96b","fd2a9f24f914bdb304c684a29467984973c171ebd360fc217af0e724c124efa0"],"sha256":"45d01368b2cd432fc9adb4a0859b5a8b7fa0d05614745c24e5baa117356efec4","data":""},"assets/support-contacts.js":{"previous":["52093e978a36f5a1e0705840a94041cb41951958960ff1b306b9aff99584b01a"],"sha256":"06196738237225639e5857bd71475e2162e0a1a1d9a79985d085c5c300ede94d","data":""},"assets/support.css":{"previous":["3f1e19d66004fdb54030128e191ca0f1ecc0fd6cb3f83923a975c67248a5a035","ca73ca52ae1156c361f9e3e4f8f67127e12159b3f1a2e8ed693edd8bc4e8fa33"],"sha256":"3f1e19d66004fdb54030128e191ca0f1ecc0fd6cb3f83923a975c67248a5a035","data":""},"support/index.html":{"previous":["2f2250632e92f8c291cbb4eeab2eda488e3c4ae6a20dc57f91a76869c9fea190","502e877021f70f3a09429a07fb1dd89898027aced4250858b7d4c605d72bc399","afcf6cc449c41c3da86da854589842aff59587d25377e2cbe5ed8625f5127f1d"],"sha256":"f956b3c6e47412a41b0c91d680f7fa94c7f003acf36980132f2f54af2020da7a","data":""}}''')


def digest(data):
    return hashlib.sha256(data).hexdigest()


def atomic_write(path, data):
    fd, name = tempfile.mkstemp(prefix='.ff-chat-', dir=path.parent)
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(name, stat.S_IMODE(path.stat().st_mode) if path.exists() else 0o644)
        os.replace(name, path)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def activate(web):
    original, updated = {}, {}
    for relative, item in MANIFEST.items():
        path = web / relative
        if path.parent.is_symlink() or path.is_symlink():
            raise ValueError('Symlink refused: ' + relative)
        if not path.parent.is_dir() or (path.exists() and not path.is_file()):
            raise ValueError('Unexpected path: ' + relative)
        data = base64.b64decode(item['data'])
        if digest(data) != item['sha256']:
            raise ValueError('Invalid embedded release: ' + relative)
        old = path.read_bytes() if path.exists() else None
        if old == data:
            continue
        if old is None or digest(old) not in item['previous']:
            raise ValueError('Unexpected existing file; refusing overwrite: ' + relative)
        original[path], updated[path] = old, data
    if not updated:
        return None
    backup = web.parent / 'backups' / ('support-chatwoot-' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '-' + str(os.getpid()))
    backup.mkdir(parents=True, exist_ok=False)
    for path, old in original.items():
        if old is not None:
            dest = backup / path.relative_to(web)
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, dest)
    (backup / 'new-files.json').write_text(json.dumps([str(p.relative_to(web)) for p, old in original.items() if old is None]))
    changed = []
    try:
        for path, data in updated.items():
            atomic_write(path, data)
            changed.append(path)
    except Exception:
        for path in reversed(changed):
            if original[path] is None:
                path.unlink()
            else:
                atomic_write(path, original[path])
        raise RuntimeError('Activation failed; changed files restored. Backup: ' + str(backup))
    return backup


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--web', default='/opt/flavorflow-saas/web')
    args = parser.parse_args()
    if os.geteuid() != 0:
        parser.error('Run with sudo on the existing hosting VM.')
    try:
        backup = activate(Path(args.web).resolve())
    except (OSError, ValueError, RuntimeError) as error:
        parser.exit(1, str(error) + '\n')
    print('Chatwoot installed; tawk.to removed from active support files.')
    print('Backup: ' + str(backup) if backup else 'Already installed; no files changed.')
    print('Email and phone preserved. No backend, DNS or Caddy changes. Confirm the Hacker free plan in your Chatwoot dashboard.')
    print('Open https://support.flavorflow.co.in/ — chat auto-opens when available; Support / Chat fallback stays accessible.')
    print('Send a test message, reply from Chatwoot Inbox, then refresh to verify a fresh visitor session. Previous inbox records are not deleted.')


if __name__ == '__main__':
    main()
